const req = $json;
const body = req.body ?? req;
const required = ['tenant_id','workflow_id','invocation_id','idempotency_key','schema_version'];
for (const key of required) {
  if (!body[key]) throw new Error(`Missing ${key}`);
}
if (!String(body.schema_version).startsWith('2.')) throw new Error('Unsupported Jahorin n8n schema');
return [{
  json: {
    ...body,
    received_at: new Date().toISOString(),
    phase: 'acting',
    input: body.input ?? {},
    memory_context: Array.isArray(body.memory_context) ? body.memory_context : [],
  }
}];

const input = $json.input ?? {};
const sources = Array.isArray(input.sources) ? input.sources : [];
return [{
  json: {
    workflow_id: $json.workflow_id,
    status: 'completed',
    result: {
      query: input.query ?? input.intent ?? '',
      sources,
      synthesis: input.synthesis ?? input.result ?? null,
      handoff: 'wepwawet',
    },
    evidence: [{
      kind: 'research_result',
      source: 'wepwawet',
      at: new Date().toISOString(),
      source_count: sources.length,
    }],
  }
}];
